describe('Form Autocomplete Attributes', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should set autocomplete attributes correctly on form fields', () => {
    // Verify autocomplete attribute is present on name field
    cy.get('[data-testid="name-input"]').should('have.attr', 'autocomplete');
    cy.get('[data-testid="name-input"]').should('have.attr', 'autocomplete', 'given-name');

    // Verify autocomplete attribute is present on email field
    cy.get('[data-testid="email-input"]').should('have.attr', 'autocomplete');
    cy.get('[data-testid="email-input"]').should('have.attr', 'autocomplete', 'email');

    // Verify autocomplete attribute is present on phone field
    cy.get('[data-testid="phone-input"]').should('have.attr', 'autocomplete');
    cy.get('[data-testid="phone-input"]').should('have.attr', 'autocomplete', 'tel');

    // Verify autocomplete attribute is present on address line 1
    cy.get('[data-testid="address-input"]').should('have.attr', 'autocomplete');
    cy.get('[data-testid="address-input"]').should('have.attr', 'autocomplete', 'address-line1');

    // Verify autocomplete attribute is present on zip code field
    cy.get('[data-testid="zip-input"]').should('have.attr', 'autocomplete');
    cy.get('[data-testid="zip-input"]').should('have.attr', 'autocomplete', 'postal-code');

    // Verify autocomplete attribute is present on country dropdown
    cy.get('[data-testid="country-select"]').should('have.attr', 'autocomplete');
    cy.get('[data-testid="country-select"]').should('have.attr', 'autocomplete', 'country');

    // Fill form and submit
    cy.get('[data-testid="name-input"]').type('John');
    cy.get('[data-testid="email-input"]').type('john@example.com');
    cy.get('[data-testid="phone-input"]').type('555-123-465');
    cy.get('[data-testid="address-input"]').type('123 Main St');
    cy.get('[data-testid="zip-input"]').type('12343');
    cy.get('[data-testid="country-select"]').select('United States');
    cy.get('[data-testid="submit-button"]').click();

    // Verify form submission success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Form submitted successfully');
  });

  it('should handle missing autocomplete attributes gracefully', () => {
    // Navigate to a form with missing autocomplete attributes
    cy.visit('/form-no-autocomplete');

    // Verify that form still functions without autocomplete
    cy.get('[data-testid="name-input"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="phone-input"]').should('be.visible');

    // Fill form without autocomplete
    cy.get('[data-testid="name-input"]').type('Jane');
    cy.get('[data-testid="email-input"]').type('jane@example.com');
    cy.get('[data-testid="phone-input"]').type('555-567-700');

    // Submit form
    cy.get('[data-testid="submit-button"]').click();

    // Verify form submission still works
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Form submitted successfully');

    // Verify error message is not displayed
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});
